   {
      case LIGHT_STANCE:    maxDamage = baseDamage * (0.5 + 0.5 * this.lightMastery * 0.01); break;
      case BALANCED_STANCE: maxDamage = baseDamage * (1 + 0.5 * this.balancedMastery * 0.01); break;
      case HEAVY_STANCE:
      case DUAL_STANCE:
      case REVERSED_STANCE: maxDamage = baseDamage * 1.5;
   }

